/**
 * The source's own copy, key for key.
 *
 * `shipany-dir` writes every string through paraglide (`m['directory.tools.title']()`),
 * so the English and Chinese are already written and reviewed. Porting the pages
 * without porting the strings would mean retyping ~180 lines of copy by hand and
 * losing the exact wording in the process, so this file is generated from the
 * source's `messages/en.json` and `messages/zh.json` — key names unchanged, so a
 * grep for `directory.detail.what_is` still finds the source's line.
 *
 * Placeholders keep paraglide's `{name}` syntax; `useDirectoryCopy()` fills them.
 *
 * One key is overridden: `directory.brand_name` is the source's demo brand
 * ("ShipAny Dir"). This build is Product Atlas, and the brand appears inside page
 * titles and `{brand}` templates, so it is replaced rather than ported.
 */

export interface CopyPair {
  en: string
  zh: string
}

